Hypothesis AF_SC : forall Σ m, ART RT Σ m -> icells_strchr m.

Local Ltac ul := unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK, kHighShadowEnd in *; lia.

Theorem strchr_liftF : strchr_icontractF RT.
Proof using AF RIP AF_IC AF_SHW AF_SC.
